    // PROBE-END: P082
    g_hkWallHit = BdHook(base, kBdWallHitRva, (void*)&detour_wallHit, (void**)&orig_wallHit);
    g_hkDoorHit = BdHook(base, kBdDoorHitRva, (void*)&detour_doorHit, (void**)&orig_doorHit);
